// ─── Typography (DESIGN.md §4) ──────────────────────────────────────────────

/** Poppins weight files, loaded in the app root via @expo-google-fonts/poppins. */
export const fontFamily = {
  400: 'Poppins_400Regular',
  500: 'Poppins_500Medium',
  600: 'Poppins_600SemiBold',
  700: 'Poppins_700Bold',
} as const;

type TextToken = { fontSize: number; lineHeight: number; fontFamily: string; letterSpacing: number; fontVariant?: 'tabular-nums'[] };

const textStyle = (size: number, lineHeight: number, weight: keyof typeof fontFamily, letterSpacing = 0): TextToken => ({
  fontSize: size,
  lineHeight,
  fontFamily: fontFamily[weight],
  letterSpacing,
});

export const type = {
  display: textStyle(34, 40, 700, -0.5),
  title1: textStyle(28, 34, 700, -0.5),
  title2: textStyle(22, 28, 600),
  headline: textStyle(17, 24, 600),
  body: textStyle(16, 24, 400),
  callout: textStyle(14, 20, 500),
  caption: textStyle(12, 16, 500),
  mono: { ...textStyle(16, 24, 500), fontVariant: ['tabular-nums'] },
} satisfies Record<string, TextToken>;
export type TypeToken = keyof typeof type;

/** Numbers that change (fare, ETA, seats left) use tabular figures. */
export const tabularNums: 'tabular-nums'[] = ['tabular-nums'];

